const thumbnailCache=new Map();
function renderThumbnail(canvas,machineOrPart){try{const cacheKey=JSON.stringify(machineOrPart);let cached=thumbnailCache.get(cacheKey);if(!cached){thumbCanvas||=document.createElement('canvas');thumbCanvas.width=thumbCanvas.height=220;thumbRenderer||=new Renderer(thumbCanvas);const g=new Geometry();let params;
 if(typeof machineOrPart==='string'){g.cylinder([0,0,0],[0,.08,0],.9,'#2f3d42',24);g.module({id:machineOrPart,pattern:'racing'},machine.paint||'#e5a849');params={target:[0,.78,-.12],yaw:-2.3,elevation:.62,span:2.65};}
 else{g.machine(machineOrPart);const fit=fittedSpan(machineOrPart,1,-2.55,.62);params={target:fit.center,yaw:-2.55,elevation:.62,span:fit.span-.5};}
 thumbRenderer.render(g,params);cached=document.createElement('canvas');cached.width=cached.height=220;cached.getContext('2d').drawImage(thumbCanvas,0,0);thumbnailCache.set(cacheKey,cached);if(thumbnailCache.size>90)thumbnailCache.delete(thumbnailCache.keys().next().value);}
 const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(cached,0,0,canvas.width,canvas.height);
 }catch{const ctx=canvas.getContext('2d');ctx.fillStyle='#b9c9c2';ctx.textAlign='center';ctx.font='bold 18px sans-serif';ctx.fillText(typeof machineOrPart==='string'?BY_ID[machineOrPart].name:machineOrPart.name,canvas.width/2,canvas.height/2);}}
