function drawMinimap(){const canvas=$('#minimap');if(!canvas||!battle)return;const c=canvas.getContext('2d'),sx=canvas.width/WIDTH,sy=canvas.height/HEIGHT;c.fillStyle='#17272de8';c.fillRect(0,0,canvas.width,canvas.height);for(const t of battle.arena.terrain){c.fillStyle=({lava:'#ae623b',vent:'#84603d',ice:'#7598a6',mud:'#55513d',oil:'#334c52',ridge:'#987456',sand:'#8a7c5a',coolant:'#59aa86',rubble:'#978066'})[t.type];c.fillRect(t.x*sx,t.y*sy,t.w*sx,t.h*sy);}for(const b of battle.obstacles()){c.fillStyle='#9aa9a7';c.fillRect(b.x*sx,b.y*sy,b.w*sx,b.h*sy);}c.strokeStyle=battle.node.owner===0?'#76dfc6':battle.node.owner===1?'#df9b80':'#b8b597';c.beginPath();c.arc(120,80,18,0,Math.PI*2);c.stroke();for(const p of battle.pickups){if(battle.time<p.ready)continue;c.fillStyle='#a6e7b2';c.fillRect(p.x*sx-3,p.y*sy-3,6,6);}for(const v of battle.vehicles){c.fillStyle=v.side?'#f3a085':'#73ead4';c.beginPath();c.arc(v.x*sx,v.y*sy,v.dead?3:5,0,Math.PI*2);c.fill();if(!v.dead){const a=v.a+(v.front||0)*Math.PI/2-Math.PI/2;c.strokeStyle=c.fillStyle;c.lineWidth=2;c.beginPath();c.moveTo(v.x*sx,v.y*sy);c.lineTo(v.x*sx+Math.cos(a)*12,v.y*sy+Math.sin(a)*12);c.stroke();c.lineWidth=1;}if(v.side===0&&v.waypoint){c.strokeStyle='#73ead4';c.beginPath();c.moveTo(v.x*sx,v.y*sy);c.lineTo(v.waypoint.x*sx,v.waypoint.y*sy);c.stroke();}}if(battle.time>55){c.strokeStyle='#eba15d';c.beginPath();c.arc(120,80,battle.ring*sx,0,Math.PI*2);c.stroke();}}
function finishBattle(){running=false;paused=false;if(!battle.replaying)matchSource.commands=clone(battle.commands);updateHUD();$('#pause-btn').disabled=true;$('#replay-btn').disabled=false;$('#arena-select').disabled=!!challenge;$('#seed-btn').disabled=!!challenge;$$('[data-enemy]').forEach(b=>b.disabled=!!challenge);$('#mirror-rival').disabled=!!challenge;const r=battle.result,won=r.winner===0,draw=r.winner<0,v=battle.vehicles[0];if(won&&!battle.replaying&&matchSource.enemy!==null){wins[matchSource.enemy]=true;try{localStorage.setItem('wm-wins-v2',JSON.stringify(wins));}catch{}}if(sound)beep(won?660:130,.3,.08,'triangle');
 const advice=battleAdvice(battle).notes[0];
 const overlay=$('#fight-overlay');overlay.hidden=false;overlay.innerHTML=`<div class="match-card"><small>${officialReceipt?'VERIFIED REPLAY · ':''}${esc(r.reason.toUpperCase())}</small><h2 style="color:${won?'var(--gold)':draw?'var(--text)':'var(--red)'}">${won?'VICTORY.':draw?'STALEMATE.':'OUTENGINEERED.'}</h2><div class="result-grid"><div><strong>${r.time.toFixed(1)}s</strong><small>BATTLE TIME</small></div><div><strong>${r.damage[0]}</strong><small>DAMAGE</small></div><div><strong>${v.intercepts}</strong><small>INTERCEPTIONS</small></div></div><p>${esc(advice)}</p><p class="hint">Autonomous trial · ${v.pickups} caches · ${v.detached} part${v.detached===1?'':'s'} collapsed</p><div class="modal-footer"><button id="battle-report-btn">Battle report</button><button id="watch-replay">↻ Exact replay</button><button class="primary" id="result-tune">Refit machine</button></div><div class="result-extras"><button id="fight-again">${officialReceipt?'Back to contract':'Fight again'}</button><button id="inspect-wreck">Inspect wreckage</button></div></div>`;$('#battle-report-btn').onclick=showBattleReport;$('#watch-replay').onclick=()=>startBattle(true);$('#result-tune').onclick=workshop;$('#fight-again').onclick=()=>officialReceipt?bountyUI.open(bountyContext.id):startBattle(false);$('#inspect-wreck').onclick=()=>{overlay.hidden=true;inspectMode=true;$('#inspect-btn').classList.add('active');drawArena();};$('#fight-state').textContent=won?'VICTORY':draw?'DRAW':'DEFEAT';startArenaIdle();
}
function renderEngineering(){const node=$('#engineering-report');if(!node)return;const notes=engineeringReport(machine,rules,arenaId);node.innerHTML=notes.map(n=>`<button class="engineering-note ${n.level}" data-engineering-category="${n.category}"><span>${n.level==='good'?'✓':n.level==='error'?'!':'↗'}</span><span>${esc(n.text)}<small>${n.level==='good'?'Review components':'Browse '+n.category.toLowerCase()}</small></span></button>`).join('');$$('[data-engineering-category]').forEach(b=>b.onclick=()=>{category=b.dataset.engineeringCategory;$$('[data-category]').forEach(t=>t.classList.toggle('active',t.dataset.category===category));renderParts();$('.parts-panel').scrollIntoView({behavior:'smooth',block:'start'});});}
function toggleBattleFocus(){const stage=$('#combat-stage');stage.classList.toggle('theater');$('#focus-battle-btn').textContent=stage.classList.contains('theater')?'Back to page':'Focus battle';drawArena();}
function renderWeaponMonitor(){const node=$('#weapons-monitor');if(!node||!battle)return;const v=battle.vehicles[0],groups=new Map();for(const m of v.modules){if(!BY_ID[m.id].rate&&!BY_ID[m.id].ram)continue;const status=battle.weaponStatus(v,m),key=m.id+':'+status,g=groups.get(key);if(g)g.count++;else groups.set(key,{id:m.id,status,count:1});}node.innerHTML=[...groups.values()].map(g=>`<span class="weapon-state ${['LOW POWER','OVERHEAT','OUT OF ARC','DESTROYED'].includes(g.status)?'warning':''}"><b>${esc(BY_ID[g.id].name)}${g.count>1?' ×'+g.count:''}</b><small>${g.status}</small></span>`).join('');}
function drawDamageLabels(){const node=$('#damage-labels'),canvas=$('#arena-canvas');if(!node||!canvas||!arenaRenderer)return;const box=canvas.getBoundingClientRect(),placed=[];node.innerHTML=battle.damageLabels.map(e=>{const p=arenaRenderer.project([(e.x-600)/CELL,e.h/CELL+(1-e.life/.75)*.8,(e.y-400)/CELL]);let x=p.x-box.left,y=p.y-box.top;while(placed.some(q=>Math.abs(q.x-x)<36&&Math.abs(q.y-y)<17))y-=18;placed.push({x,y});if(x<8||y<45||x>box.width-8||y>box.height-12)return '';return `<span class="damage-number ${e.side?'enemy':'own'}" style="left:${x.toFixed(1)}px;top:${y.toFixed(1)}px;opacity:${Math.min(1,e.life/.2)}">−${Math.round(e.amount)}</span>`;}).join('');}
function scoutRival(){if(running&&!paused)togglePause();const rival=opponent(),s=stats(rival),composition=new Map();for(const m of rival.modules)composition.set(m.id,(composition.get(m.id)||0)+1);const camera=newCamera();showModal('Rival intelligence',`<div class="scout-grid"><div><canvas id="scout-canvas" width="640" height="520" aria-label="Rival machine preview. Drag to orbit, pinch or scroll to zoom."></canvas><p class="hint">Drag to orbit · pinch to zoom · front ${frontNames[rival.front||0]}</p></div><div><span class="eyebrow">${challenge?'FRIEND CHALLENGE':'SELECTED RIVAL'}</span><h2>${esc(rival.name)}</h2><p>${s.cost} credits · ${s.mass} t · ${s.parts} parts · ${s.height} levels</p><p>${esc(rival.tactic)} doctrine · ${rival.range} m range · targets ${esc(rival.target)}</p><div class="scout-parts">${[...composition].map(([id,n])=>`<span><b>${n}×</b> ${esc(BY_ID[id].name)}</span>`).join('')}</div></div></div><div class="scout-notes">${engineeringReport(rival,rules,arenaId).filter(n=>n.level==='warn').slice(0,3).map(n=>`<p>◎ ${esc(n.text)}</p>`).join('')}</div><div class="modal-footer"><button data-close>Close intelligence</button><button class="primary" id="scout-refit">Build a counter</button></div>`,()=>{const canvas=$('#scout-canvas');scoutRenderer=new Renderer(canvas);const draw=()=>{if(!scoutRenderer||!canvas.isConnected)return;const fit=fittedSpan(rival,canvas.clientWidth/Math.max(1,canvas.clientHeight),camera.yaw,camera.elevation);scoutRenderer.render(workshopScene(rival,{grid:false,ghost:false}),{target:[fit.center[0]+camera.panX,fit.center[1],fit.center[2]+camera.panZ],yaw:camera.yaw,elevation:camera.elevation,span:fit.span/camera.zoom});};bindCamera(canvas,camera,{change:draw});draw();window.addEventListener('resize',draw);modalCleanup=()=>{window.removeEventListener('resize',draw);scoutRenderer?.dispose();scoutRenderer=null;};$('#scout-refit').onclick=()=>{closeModal();workshop();};});}
function showBattleReport(){const report=battleAdvice(battle),v=battle.vehicles[0];showModal('Battle engineering report',`<div class="report-score"><div><strong>${report.ownIntegrity}%</strong><span>YOUR INTEGRITY</span></div><div><strong>${report.enemyIntegrity}%</strong><span>RIVAL INTEGRITY</span></div><div><strong>${v.shots} / ${v.hits}</strong><span>SHOTS / IMPACTS</span></div></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Weapon</th><th>Fitted / left</th><th>Shots</th><th>Damage</th></tr></thead><tbody>${report.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.count} / ${r.alive}</td><td>${r.shots}</td><td>${Math.round(r.damage)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Weapon damage includes its direct, splash, and chain hits to enemy parts; shield absorption and secondary reactor explosions are separate. Piercing shots can produce multiple impacts.</p><div class="report-advice">${report.notes.map(n=>`<p>↗ ${esc(n)}</p>`).join('')}</div><div class="modal-footer"><button data-close>Back to result</button><button class="primary" id="report-refit">Refit with this in mind</button></div>`,()=>{$('#report-refit').onclick=()=>{closeModal();workshop();};});}
function initAudio(){try{audioCtx||=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();}catch{sound=false;}}
function beep(hz,duration,volume,type='sine'){if(!sound||!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(hz,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,hz*.3),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}
function historyReplace(){window.history.replaceState(null,'',location.pathname+location.search);}
function manual(){showModal('The engineer’s field manual',`<div class="manual-grid">
 <section><h3>Build in three dimensions</h3><p>Select a component and tap a socket to install it. Fitted parts are protected from accidental replacement; enable Replace parts to swap them. Engineering report warnings explain power, cooling, and structural weaknesses. Choose Level 1 or 2 to build upward. Every upper part needs a frame, deck, core, or armor directly underneath. Unsupported columns collapse in battle. The core, wheels, treads, and ram wedges belong on the ground.</p></section>
 <section><h3>Work within the class</h3><p>Standard class allows 1,200 credits, 32 fitted parts plus one required command core, 360 tonnes, and eight weapons. Use Match rules for Skirmish, Heavy, or custom caps. Set a custom cap to zero for no limit. Unlimited removes all four caps; the physical 9×9×3 grid and support rules still apply. Friend challenges lock the same rules and combat mode for both builds. Mirror sparring copies your build, so it fits any class. Upper mounts cost 12 credits per level. Reinforcing adds 35% health, 25% mass, and 30% cost. Overclocking adds 20% weapon or system output, 35% cost, and reduces health 15%; weapons also produce 30% more heat. The first two copies of a weapon retain normal reload; each extra matching gun adds 18% reload time from shared fire-control bandwidth. The Engineering report gives the exact multiplier.</p></section>
 <section><h3>Make it yours</h3><p>Choose a hull, accent, light color, livery, and unit number. The Front selector marks your fighting nose with a lit chevron and headlights; this side faces the opponent in battle. “Turn mounts too” rotates your installed guns and mobility with the new front. Uncheck it to preserve individual firing arcs. Paint mode colors individual parts. Inspect a fitted part to rotate, upgrade, or recolor it. Build mode selects existing parts by default; enable Replace parts when you want to swap equipment. Mirror mode installs or removes matching chassis positions. Use Exploded view to understand a stack, or hide upper levels to work underneath.</p></section>
 <section><h3>Control the camera</h3><p>Drag to orbit and tilt. Scroll or pinch to zoom. Right-drag, Shift-drag, or two-finger drag to pan. Fit restores the view. In battle, follow your machine, follow the rival, frame both, or explore freely. The fullscreen button gives the arena more room.</p></section>
 <section><h3>Engineer the behavior</h3><p>Choose movement doctrine, preferred range, target priority, and damage response in the workshop. Both machines run those instructions automatically. Pause, inspect, replay, and compare weapon performance to improve the next revision. Camera and playback controls never change the outcome.</p></section>
 <section><h3>Automatic systems</h3><p>Boost trades 25 energy and 12 heat for speed. Coolant purge spends 20 energy to remove 45 heat but locks guns for 1.2 seconds. Brace spends 30 energy for 45% damage reduction and slower movement for three seconds. Smoke needs a Veil launcher and 20 energy; it breaks missile tracking and worsens enemy accuracy for five seconds. Both machines trigger these systems when their sensors detect high heat, incoming damage, or a distant target. Each needs power and has a cooldown. An Afterburner improves automatic boost.</p></section>
 <section><h3>Experimental arsenal</h3><p>Prism lasers hit instantly. Helios plasma bypasses half of armor. Storm coils chain through three nearby parts. Rupture scatterguns fire six pellets; Cyclone gatlings spin up during sustained fire. Frost lances slow targets and lower their heat. Widow minelayers drop armed traps behind your marked front, up to three live mines per launcher. Ceramic plating resists thermal weapons; blast cages resist explosives. Fusion reactors power hungry builds but explode when destroyed. Majority-hover builds float above damaging surfaces and ignore poor traction, but still absorb ambient heat.</p></section><section><h3>Layer your defenses</h3><p>Reactive armor reduces the first hit of 35 or more damage by 75%, on top of its armor. Fortress bulkheads reduce damage 52%. Sentinels intercept rockets and mortars for eight energy per shot. Shields recharge after a break in damage; repairs restore damaged connected parts. Batteries can explode into neighboring parts across levels.</p></section>
 <section><h3>Height changes the fight</h3><p>Shots travel through three-dimensional space. Elevated guns can shoot over low obstacles and ground armor. Towers are exposed and reduce steering stability. Mortars arc over cover and explode on impact. Damage to a support can bring every part above it down.</p></section>
 <section><h3>Use the ground</h3><p>Sand and mud slow wheels; treads retain most of their traction. Ice cools systems but reduces grip. Oil also reduces grip. Furnace vents erupt for four seconds in every twelve, starting at eight seconds. Lava and active vents damage parts and add heat. Redline Ridge has raised firing positions. Coolant channels increase cooling by 70% but slow wheels; rubble cuts wheel speed by 35%. Treads preserve most speed on both. Raised terrain also blocks low shots crossing the ridge. Most cover can be destroyed.</p></section>
 <section><h3>Fight for resources</h3><p>Occupy the central ring alone for three seconds to gain eight energy per second. Leave it and you lose control. Green caches restore up to 100 HP across surviving parts and 30 energy, then respawn after 25 seconds. At 55 seconds the containment field starts closing. At 100 seconds the higher percentage of surviving integrity wins; within 2.5 points is a draw.</p></section>
 <section><h3>Test and replay</h3><p>Every match runs automatically from the saved doctrine and seed. Exact replay repeats that same experiment. Playback speed and camera movement only change how you watch. Focus battle gives the machines room on small screens. Tap a part to inspect it. Weapon status explains reloads, firing arcs, and shortages; Battle report shows damage contribution and refit advice. Scout rival before building your counter. Older live-command challenges import as autonomous trials.</p></section>
 <section><h3>Keep and share your machines</h3><p>Your build autosaves on this device. Save up to eight named blueprints or export JSON files. Old Foundry blueprints still import. Challenge links contain all parts, layers, upgrades, colors, front direction, arena, seed, and match rules. Host the static game anywhere you choose. Your friend needs access to your host; for large builds or another host, exchange JSON challenge files. Sandbox battles stay on each player’s device. Bounty links use your game server and keep authoritative results there.</p></section><section><h3>Bounties & demo credits</h3><p>Open Contracts and create a demo profile with 1,000 credits. These have no cash value. Scout a contract, refit within its locked construction limits, and practice free. Official entry spends the listed fee once; the server runs the battle. A win pays the reserved reward and closes the bounty. A loss or draw consumes entry and reopens it; a technical failure refunds entry. Only one official challenger is accepted at a time. Set per-entry and daily spending caps from your balance button. Create a contract by reserving its reward, then share its link. Unlisted links can still be viewed by anyone who receives them. External agents can use restricted API keys; they bring their own models and compute.</p></section></div><div class="modal-footer"><button class="primary" data-close>Back to the foundry</button></div>`);}
