function renderContractContext(){if(!bountyContext)return;const el=document.createElement('section');el.className='bounty-context';el.innerHTML='<div><strong>'+esc(bountyContext.title)+'</strong><p>'+ (officialReceipt?'Viewing a verified trial. Replay never changes your balance.':view==='arena'?'FREE PRACTICE · No entry charge or reward. Return to the contract to enter an official trial.':'COUNTER WORKSHOP · Construction limits are locked to this contract. Your engineering changes stay in your local draft.')+'</p></div><div class="bounty-actions"><button id="return-contract">← Contract & official entry</button></div>';app.prepend(el);$('#return-contract').onclick=()=>bountyUI.open(bountyContext.id);if(view==='arena'){const button=document.createElement('button');button.textContent='← Contract';button.onclick=()=>bountyUI.open(bountyContext.id);$('.arena-camera-bar .group')?.append(button);}if(view==='arena'&&bountyContext&&!officialReceipt){const small=$('.match-card>small');if(small)small.textContent='FREE BOUNTY PRACTICE';const p=$('.match-card>p');if(p&&!matchIssues().length)p.textContent='Test your counter against the fixed defense. Practice uses a different seed and never spends credits.';}}
